 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The markers define horizontal/vertical line segments. Fill only gaps
    # that are flanked by marker cells; do not bridge gaps outside those runs.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            left = c - 1
            while left >= 0 and grid[r][left] == 1:
                left -= 1
            right = c + 1
            while right < w and grid[r][right] == 1:
                right += 1
            # handled via each pair of consecutive markers below
        cols = [c for c, v in enumerate(grid[r]) if v == 1]
        for a, b in zip(cols, cols[1:]):
            if b > a + 1:
                for c in range(a + 1, b):
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 1]
        for a, b in zip(rows, rows[1:]):
            if b > a + 1:
                for r in range(a + 1, b):
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    test = [[8,8,1,1,1,1,1,1,8],[8,8,1,8,1,8,8,8,8],[8,8,8,8,1,8,8,8,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,8,8,8,1,8],[8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8]]
    for row in transform(test): print(*row)
",
